60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper) {
79	        this.clinicService = clinicService;
80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	    }
84	
85	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
86	    @Override
87	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
88	        Collection<Owner> owners;
89	        if (lastName != null) {
90	            owners = this.clinicService.findOwnerByLastName(lastName);
91	        } else {
92	            owners = this.clinicService.findAllOwners();
93	        }
94	        if (owners.isEmpty()) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
103	        Owner owner = this.clinicService.findOwnerById(ownerId);
104	        if (owner == null) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
108	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
109	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
110	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto);
117	        prepareNewOwner(ownerFieldsDto, registrationDate);
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        owner.setRegistrationDate(registrationDate);
121	        owner.setCustomerCode(customerCodeFor(owner));
122	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
123	        applyPossibleDuplicate(owner);
124	        assignHousehold(owner, ownerFieldsDto);
125	        this.clinicService.saveOwner(owner);
126	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
127	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
128	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
129	            owner.getMembershipLevel());
130	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
131	        ownerDto.setBulkSignupWarning(bulkSignupWarning(registrationDate));
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
134	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
140	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
141	        if (currentOwner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        currentOwner.setAddress(ownerFieldsDto.getAddress());
145	        currentOwner.setCity(ownerFieldsDto.getCity());
146	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
147	        currentOwner.setLastName(ownerFieldsDto.getLastName());
148	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
149	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
150	        this.clinicService.saveOwner(currentOwner);
151	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Transactional
156	    @Override
157	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
158	        Owner owner = this.clinicService.findOwnerById(ownerId);
159	        if (owner == null) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        this.clinicService.deleteOwner(owner);
163	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
164	    }
