218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
221	        Owner owner = this.clinicService.findOwnerById(ownerId);
222	        if (owner != null) {
223	            Pet pet = owner.getPet(petId);
224	            if (pet != null) {
225	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
226	            }
227	        }
228	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
229	    }
230	
231	    /**
232	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
233	     * The address is normalized in place (so a required-field check that follows rejects an
234	     * address blank after normalization), the required fields are checked, the telephone and
235	     * email are normalized in place, and the resulting owner is rejected when its derived
236	     * identity key already belongs to another owner. Each rule
237	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
238	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
239	     * to be mapped and saved.
240	     *
241	     * @param ownerFieldsDto the submitted owner fields, normalized in place
242	     */
243	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
244	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
245	        validateRequiredFields(ownerFieldsDto);
246	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
247	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
248	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
249	        rejectDuplicateIdentity(ownerFieldsDto);
250	        rejectCityAtCapacity(ownerFieldsDto.getCity());
251	        rejectDailyLimitExceeded(registrationDate);
252	    }
253	
254	    /**
255	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
256	     * falls on a business day. The date supplied on the request is used when present, otherwise the
257	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
258	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
259	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
260	     * membership number's year segment, the per-day create limit) is computed against.
261	     *
262	     * A supplied registration date later than the server's current date is rejected with an
263	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
264	     *
265	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
266	     * @return the effective registration date rolled forward to the next business day
267	     */
268	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
269	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
270	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
271	            throw new InvalidFieldsException(List.of("registrationDate"));
272	        }
273	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
274	        return toBusinessDay(effective);
275	    }
276	
277	    /**
278	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
279	     * following Monday, while a weekday is returned unchanged.
280	     *
281	     * @param date the date to adjust
282	     * @return the same date when it is a weekday, otherwise the next Monday
283	     */
284	    private LocalDate toBusinessDay(LocalDate date) {
285	        java.time.DayOfWeek day = date.getDayOfWeek();
286	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
287	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
288	        }
289	        return date;
290	    }
291	
292	    /**
293	     * The maximum number of owners that may be created on a single day. Once this many owners
294	     * already carry today's {@code registrationDate}, no further owner may be created today.
295	     */
296	    private static final long DAILY_OWNER_LIMIT = 100L;
297	
298	    /**
299	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
300	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
301	     * date the new owner would be stored with, so owners are capped per business day. When the limit
302	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
303	     * advice renders as a 429 Too Many Requests response.
304	     *
305	     * @param registrationDate the adjusted business-day registration date of the owner being created
306	     */
307	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
308	        long count = this.clinicService.findAllOwners().stream()
309	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
310	            .count();
311	        if (count >= DAILY_OWNER_LIMIT) {
312	            throw new DailyOwnerLimitExceededException(registrationDate);
313	        }
314	    }
315	
316	    /**
317	     * The number of owners that may carry a single day's {@code registrationDate} before that day
318	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
319	     * the create and read responses report {@code bulkSignupWarning} true for that date.
320	     */
321	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
322	
323	    /**
324	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
325	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
326	     * count is taken against the same adjusted date owners are stored with, mirroring the
327	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
328	     *
329	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
330	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
331	     */
332	    private boolean bulkSignupWarning(LocalDate registrationDate) {
333	        if (registrationDate == null) {
334	            return false;
335	        }
336	        long count = this.clinicService.findAllOwners().stream()
337	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
338	            .count();
339	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
340	    }
341	
342	    /**
343	     * The maximum number of owners a single city may hold. Once a city already contains this
344	     * many owners, no further owner may be created in it.
345	     */
346	    private static final long CITY_OWNER_CAPACITY = 50L;
347	
348	    /**
349	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
350	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
351	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
352	     * which the exception advice renders as a 409 Conflict response.
353	     *
354	     * @param city the city of the owner being created
355	     */
356	    private void rejectCityAtCapacity(String city) {
357	        long count = this.clinicService.findAllOwners().stream()
358	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
359	            .count();
360	        if (count >= CITY_OWNER_CAPACITY) {
361	            throw new CityCapacityExceededException(city);
362	        }
363	    }
364	
365	    /**
366	     * Builds the customer code assigned to a newly created owner. The code is formatted as
367	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the owner's canonical region (see
368	     * {@link Owner#getRegion()}), rendered {@code 'UNKNOWN'} when the owner has no known region,
369	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest over the
370	     * owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}. The code
371	     * carries no sequence number, so two owners sharing a region, telephone and last name resolve to
372	     * the same code. The whole owner is taken so the code is derived from whichever of its fields the
373	     * identity scheme needs.
374	     *
375	     * @param owner the owner being created, whose fields the code is derived from
376	     * @return the formatted customer code
377	     */
378	    private String customerCodeFor(Owner owner) {
379	        String region = owner.getRegion();
380	        String regionCode = region != null ? region : "UNKNOWN";
381	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
382	        return regionCode + "-" + hash8;
383	    }
384	
385	    /**
386	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
387	     * with the owner being created, compared case-insensitively. The count is taken before the
388	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
389	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
390	     *
391	     * @param firstName the first name of the owner being created
392	     * @param lastName the last name of the owner being created
393	     * @return the number of pre-existing owners sharing the same first and last name
394	     */
395	    private int countNamesakes(String firstName, String lastName) {
396	        return (int) this.clinicService.findAllOwners().stream()
397	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
398	                && lastName.equalsIgnoreCase(existing.getLastName()))
399	            .count();
400	    }
401	
402	    /**
403	     * Flags a newly created owner as a possible (soft) duplicate. Reaching this point means the
404	     * owner already cleared {@link #rejectDuplicateIdentity(OwnerFieldsDto)}, so it is not a hard
405	     * duplicate. It is nonetheless a possible duplicate when an existing owner shares its
406	     * {@code lastName} (compared case-insensitively) and its {@code postcode} while carrying a
407	     * different (normalized) {@code telephone}. When such an owner is found, {@code possibleDuplicate}
408	     * is set {@code true} and {@code possibleDuplicateOf} to the matching owner's id; otherwise
409	     * {@code possibleDuplicate} is set {@code false} and no matching id is recorded. An owner without
410	     * a postcode can share no postcode and is never a possible duplicate.
411	     *
412	     * @param owner the owner being created, already carrying its normalized telephone and postcode
413	     */
414	    private void applyPossibleDuplicate(Owner owner) {
415	        owner.setPossibleDuplicate(false);
416	        owner.setPossibleDuplicateOf(null);
417	        if (owner.getPostcode() == null) {
418	            return;
419	        }
420	        this.clinicService.findAllOwners().stream()
421	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
422	                && owner.getPostcode().equals(existing.getPostcode())
423	                && !owner.getTelephone().equals(existing.getTelephone()))
424	            .findFirst()
425	            .ifPresent(existing -> {
426	                owner.setPossibleDuplicate(true);
427	                owner.setPossibleDuplicateOf(existing.getId());
428	            });
429	    }
430	
431	    /**
432	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
433	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
434	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
435	     * the names of every offending field, which the exception advice renders as a 400 response
436	     * with an {@code errors} array.
437	     *
438	     * @param ownerFieldsDto the submitted owner fields
439	     */
440	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
441	        List<String> missing = new ArrayList<>();
442	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
443	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
444	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
445	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
446	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
447	        if (!missing.isEmpty()) {
448	            throw new RequiredFieldsMissingException(missing);
449	        }
450	    }
451	
452	    private void addIfBlank(List<String> missing, String fieldName, String value) {
453	        if (value == null || value.isBlank()) {
454	            missing.add(fieldName);
455	        }
456	    }
457	
458	    /**
459	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
460	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
461	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
462	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
463	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
464	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
465	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
466	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
467	     *
468	     * @param telephone the submitted telephone value
469	     * @return the normalized E.164 telephone
470	     */
471	    private String normalizeTelephone(String telephone) {
472	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
473	        String e164;
474	        if (cleaned.startsWith("+")) {
475	            e164 = "+" + cleaned.substring(1);
476	        } else {
477	            String national = cleaned;
478	            if (national.startsWith("0")) {
479	                national = national.substring(1);
480	            }
481	            e164 = "+61" + national;
482	        }
483	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
484	            throw new InvalidFieldsException(List.of("telephone"));
485	        }
486	        validateNationalNumberLength(e164);
487	        return e164;
488	    }
489	
490	    /**
491	     * The required national-number length (the digits after the country code) for each country
492	     * code we recognize: {@code '+61'} (Australia) requires 9 national digits and {@code '+1'}
493	     * (NANP) requires 10. Keyed by the country-code digits without the leading {@code '+'}.
494	     */
495	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
496	        java.util.Map.of("61", 9, "1", 10);
497	
498	    /**
499	     * Validates the national-number length of an already syntactically valid E.164 telephone
500	     * against its country code. For each recognized country code the digits following the code
501	     * must have exactly the expected length ({@code '+61'} => 9 national digits, {@code '+1'} =>
502	     * 10). When the country code is recognized but the national number is the wrong length an
503	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
504	     * response naming the {@code telephone} field. A country code that is not recognized carries
505	     * no per-country length rule and is left to the general 8-to-15-digit E.164 check.
506	     *
507	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
508	     */
509	    private void validateNationalNumberLength(String e164) {
510	        String digits = e164.substring(1);
511	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
512	            .filter(entry -> digits.startsWith(entry.getKey()))
513	            // longest matching country code wins, so a shorter code cannot shadow a longer one
514	            .max(java.util.Comparator.comparingInt(entry -> entry.getKey().length()))
515	            .ifPresent(entry -> {
516	                int nationalLength = digits.length() - entry.getKey().length();
517	                if (nationalLength != entry.getValue()) {
518	                    throw new InvalidFieldsException(List.of("telephone"));
519	                }
520	            });
521	    }
522	
523	    /**
524	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
525	     * and a domain containing at least one dot, none of the parts holding whitespace or a
526	     * second {@code @}.
527	     */
528	    private static final java.util.regex.Pattern EMAIL_PATTERN =
529	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
530	
531	    /**
532	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
533	     * accepted and returned unchanged. When present it must be a syntactically valid address;
534	     * the value is stored and returned lower-cased. When present but invalid an
535	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
536	     * response naming the {@code email} field.
537	     *
538	     * @param email the submitted email value, or {@code null} when omitted
539	     * @return the lower-cased email, or {@code null} when none was supplied
540	     */
541	    private String normalizeEmail(String email) {
542	        if (email == null) {
543	            return null;
544	        }
545	        String trimmed = email.trim();
546	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
547	            throw new InvalidFieldsException(List.of("email"));
548	        }
549	        return canonicalEmail(trimmed);
550	    }
551	
552	    /**
553	     * Reduces an email to the canonical form used both to store it and to compare it against
554	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
555	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
556	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
557	     * value read back off an existing owner without risk of rejecting it. This is the single
558	     * definition of email identity: two emails denote the same address exactly when they
559	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
560	     * an email already on an existing owner can be compared for equality after both pass through
561	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
562	     *
563	     * @param email the email to canonicalize, or {@code null} when none was supplied
564	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
565	     */
566	    private String canonicalEmail(String email) {
567	        if (email == null) {
568	            return null;
569	        }
570	        return email.trim().toLowerCase(java.util.Locale.ROOT);
571	    }
572	
573	    /**
574	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
575	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
576	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
577	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
578	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
579	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
580	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
581	     * 400 response naming the {@code postcode} field.
582	     *
583	     * @param postcode the submitted postcode, or {@code null} when omitted
584	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
585	     */
586	    private void validatePostcode(String postcode, String city) {
587	        if (postcode == null) {
588	            return;
589	        }
590	        if (!postcode.matches("^[0-9]{4}$")) {
591	            throw new InvalidFieldsException(List.of("postcode"));
592	        }
593	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
594	        if (range != null) {
595	            int value = Integer.parseInt(postcode);
596	            if (value < range[0] || value > range[1]) {
597	                throw new InvalidFieldsException(List.of("postcode"));
598	            }
599	        }
600	    }
601	
602	    /**
603	     * Rejects a new owner whose derived identity key is already used by any existing owner. All
604	     * duplicate detection is consolidated into this single key (see
605	     * {@link Owner#identityKey(String, String, String)}): the normalized E.164 telephone, the
606	     * canonical (trimmed, lower-cased) email and the household identifier the owner would receive,
607	     * joined by {@code '|'}. The submitted telephone and email have already been normalized in
608	     * place, and the household identifier is the value {@link #assignHousehold} would later store
609	     * (see {@link #prospectiveHouseholdId(OwnerFieldsDto)}). An owner is a duplicate only when its
610	     * whole key equals an existing owner's, so a difference in any part — for example two members
611	     * of one household with different telephones — yields distinct keys and is allowed. When a
612	     * match is found a {@link DuplicateIdentityException} is thrown, which the exception advice
613	     * renders as a 409 Conflict response.
614	     *
615	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
616	     */
617	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
618	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
619	            canonicalEmail(ownerFieldsDto.getEmail()), prospectiveHouseholdId(ownerFieldsDto));
620	        boolean taken = this.clinicService.findAllOwners().stream()
621	            .anyMatch(existing -> identityKey.equals(Owner.identityKey(existing.getTelephone(),
622	                canonicalEmail(existing.getEmail()), existing.getHouseholdId())));
623	        if (taken) {
624	            throw new DuplicateIdentityException(identityKey);
625	        }
626	    }
627	
628	    /**
629	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
630	     * set to {@code true}. The identifier is the one the owner would receive
631	     * ({@link #prospectiveHouseholdId(OwnerFieldsDto)}), derived deterministically from its
632	     * household identity so every owner in the same household resolves to the same stable value.
633	     * The new owner receives that value, and any existing household mates that do not yet carry it
634	     * are updated so the whole household shares one identifier. When the request did not opt in the
635	     * owner is left without a household identifier.
636	     *
637	     * @param owner the newly created owner, mutated in place with its household identifier
638	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
639	     */
640	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
641	        String householdId = prospectiveHouseholdId(ownerFieldsDto);
642	        if (householdId == null) {
643	            return;
644	        }
645	        owner.setHouseholdId(householdId);
646	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
647	            if (!householdId.equals(mate.getHouseholdId())) {
648	                mate.setHouseholdId(householdId);
649	                this.clinicService.saveOwner(mate);
650	            }
651	        }
652	    }
653	
654	    /**
655	     * Derives the {@code householdId} a newly submitted owner would receive, without needing the
656	     * owner to have been mapped or persisted yet. An owner shares a household only when the request
657	     * opts in via {@code sharesHousehold}; when it does, the identifier is derived deterministically
658	     * from the owner's household identity (its {@code lastName} and {@code address}, see
659	     * {@link #householdIdFor(String, String)}), so it matches the value {@link #assignHousehold} will
660	     * later store and every household mate resolves to the same identifier. When the request did not
661	     * opt in the owner belongs to no shared household and {@code null} is returned.
662	     *
663	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
664	     * @return the household identifier the owner would receive, or {@code null} when it shares none
665	     */
666	    private String prospectiveHouseholdId(OwnerFieldsDto ownerFieldsDto) {
667	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
668	            return null;
669	        }
670	        return householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
671	    }
672	
673	    /**
674	     * Derives the stable {@code householdId} shared by every owner in the household identified by
675	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
676	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
677	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
678	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
679	     *
680	     * @param lastName the household's last name
681	     * @param address the household's address
682	     * @return the deterministic household identifier
683	     */
684	    private String householdIdFor(String lastName, String address) {
685	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
686	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
687	        return "HH-" + shaHex(key, 16);
688	    }
689	
690	    /**
691	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
692	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
693	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
694	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
695	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
696	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
697	     * an {@link IllegalStateException} is thrown.
698	     *
699	     * @param input the string to hash
700	     * @param hexChars the number of leading upper-case hex characters to return
701	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
702	     */
703	    private String shaHex(String input, int hexChars) {
704	        try {
705	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
706	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
707	            StringBuilder sb = new StringBuilder();
708	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
709	                sb.append(String.format("%02X", digest[i]));
710	            }
711	            return sb.substring(0, hexChars);
712	        }
713	        catch (java.security.NoSuchAlgorithmException e) {
714	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
715	        }
716	    }
717	
718	    /**
719	     * Counts the owners that belong to the household identified by the given {@code householdId},
720	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
721	     * of owners, so after a create it reflects the household's size including the newly persisted
722	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
723	     * household and yields {@code 0}.
724	     *
725	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
726	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
727	     */
728	    private int countHouseholdMembers(String householdId) {
729	        if (householdId == null) {
730	            return 0;
731	        }
732	        return (int) this.clinicService.findAllOwners().stream()
733	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
734	            .count();
735	    }
736	
737	    /**
738	     * Finds every existing owner that shares a household with the given {@code lastName} and
739	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
740	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
741	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
742	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
743	     * every rule that reasons about households.
744	     *
745	     * @param lastName the last name to match on
746	     * @param address the address to match on
747	     * @return the owners sharing the household, in encounter order (possibly empty)
748	     */
749	    private List<Owner> findHouseholdMates(String lastName, String address) {
750	        String normalizedLastName = collapseWhitespace(lastName);
751	        String normalizedAddress = normalizeAddress(address);
752	        return this.clinicService.findAllOwners().stream()
753	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
754	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
755	            .toList();
756	    }
757	
758	    /**
759	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
760	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
761	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
762	     *
763	     * @param value the value to collapse, or {@code null}
764	     * @return the whitespace-collapsed value, never {@code null}
765	     */
766	    private String collapseWhitespace(String value) {
767	        if (value == null) {
768	            return "";
769	        }
770	        return value.trim().replaceAll("\\s+", " ");
771	    }
772	
773	    /**
774	     * Common street-type abbreviations expanded during address normalization, keyed by their
775	     * upper-cased token.
776	     */
777	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
778	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
779	
780	    /**
781	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
782	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
783	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
784	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
785	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
786	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
787	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
788	     * everywhere an address is stored or compared.
789	     *
790	     * @param address the submitted address value, or {@code null}
791	     * @return the normalized address, never {@code null}
792	     */
793	    private String normalizeAddress(String address) {
794	        if (address == null) {
795	            return "";
796	        }
797	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
798	        if (collapsed.isEmpty()) {
799	            return "";
800	        }
801	        String[] tokens = collapsed.split(" ");
802	        StringBuilder sb = new StringBuilder(collapsed.length());
803	        for (int i = 0; i < tokens.length; i++) {
804	            if (i > 0) {
805	                sb.append(' ');
806	            }
807	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
808	        }
809	        return sb.toString();
810	    }
811	}
