188	    /**
189	     * Builds the derived identity key that consolidates all owner duplicate detection into a
190	     * single value: the normalized E.164 {@code telephone}, the lower-cased {@code email}
191	     * (empty when none) and the {@code householdId} (empty when the owner shares no household),
192	     * joined by {@code '|'}. Two owners are duplicates exactly when their whole identity keys are
193	     * equal, so a difference in any of the three parts (for example two household mates with
194	     * different telephones) yields distinct keys. A {@code null} part contributes the empty string.
195	     *
196	     * @param telephone the normalized E.164 telephone
197	     * @param email the lower-cased email, or {@code null} when none
198	     * @param householdId the shared household identifier, or {@code null} when none
199	     * @return the derived identity key
200	     */
201	    public static String identityKey(String telephone, String email, String householdId) {
202	        return (telephone == null ? "" : telephone) + "|"
203	            + (email == null ? "" : email) + "|"
204	            + (householdId == null ? "" : householdId);
205	    }
206	
207	    /**
208	     * Returns this owner's derived identity key, see
209	     * {@link #identityKey(String, String, String)}.
210	     *
211	     * @return the derived identity key for this owner
212	     */
213	    @Transient
214	    public String getIdentityKey() {
215	        return identityKey(this.telephone, this.email, this.householdId);
216	    }
