218	    /**
219	     * Fixed city-to-region table: the canonical region each known city belongs to
220	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). A city
221	     * absent from this table has no known region.
222	     */
223	    private static final Map<String, String> CITY_REGIONS = Map.of(
224	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
225	
226	    /**
227	     * Resolves the canonical region a city belongs to using the fixed city-to-region table
228	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns the
229	     * region string, or {@code null} when the city has no known region. This is the single
230	     * definition of the city-to-region mapping, shared by every rule that derives a region
231	     * from an owner's city.
232	     *
233	     * @param city the city to resolve
234	     * @return the canonical region, or {@code null} when the city has no known region
235	     */
236	    public static String regionForCity(String city) {
237	        return CITY_REGIONS.get(city);
238	    }
239	
240	    /**
241	     * Fixed region-to-postcode table: the inclusive {@code {low, high}} 4-digit postcode range
242	     * each region admits ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
243	     * A region absent from this table has no fixed range.
244	     */
245	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
246	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
247	
248	    /**
249	     * Resolves the inclusive {@code {low, high}} 4-digit postcode range a region admits using the
250	     * fixed region-to-postcode table ({@code NSW 2000-2099}, {@code VIC 3000-3099},
251	     * {@code QLD 4000-4099}). Returns the range, or {@code null} when the region is {@code null} or
252	     * has no fixed range (any 4-digit postcode is then admitted). This is the single definition of
253	     * the region-to-postcode ranges, shared by every rule that relates a postcode to a region.
254	     *
255	     * @param region the region to resolve, or {@code null}
256	     * @return the inclusive {@code {low, high}} range, or {@code null} when the region has none
257	     */
258	    public static int[] postcodeRangeForRegion(String region) {
259	        return region == null ? null : REGION_POSTCODE_RANGES.get(region);
260	    }
261	
262	    /**
263	     * Resolves the canonical region a postcode belongs to by finding the fixed region-to-postcode
264	     * range that contains it ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
265	     * Returns the region string, or {@code null} when the postcode is {@code null}, not a 4-digit
266	     * value, or falls in no known range. This is the single definition of the postcode-to-region
267	     * mapping, shared by every rule that derives a region from a postcode.
268	     *
269	     * @param postcode the postcode to resolve
270	     * @return the canonical region, or {@code null} when the postcode maps to no known region
271	     */
272	    public static String regionForPostcode(String postcode) {
273	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
274	            return null;
275	        }
276	        int value = Integer.parseInt(postcode);
277	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
278	            int[] range = entry.getValue();
279	            if (value >= range[0] && value <= range[1]) {
280	                return entry.getKey();
281	            }
282	        }
283	        return null;
284	    }
285	
286	    /**
287	     * Returns the canonical region this owner belongs to. The owner's {@code postcode} is preferred:
288	     * when it falls in a known region range (see {@link #regionForPostcode(String)}) that region is
289	     * used, disambiguating cities that share a name. Only when the postcode is absent or in no known
290	     * range does derivation fall back to the fixed city-to-region table (see
291	     * {@link #regionForCity(String)}). Returns {@code null} when neither the postcode nor the city
292	     * resolves to a known region. This is the single definition of an owner's region, shared by
293	     * every rule that derives a region from an owner.
294	     *
295	     * @return the owner's canonical region, or {@code null} when it has no known region
296	     */
297	    @Transient
298	    public String getRegion() {
299	        String region = regionForPostcode(this.postcode);
300	        return region != null ? region : regionForCity(this.city);
301	    }
302	
303	    /**
304	     * Returns this owner's numeric membership level, assigned on creation. The level starts at
305	     * {@code 1}, gains {@code 1} when an email is present, gains {@code 1} when the owner has no
306	     * namesakes (namesakeCount is 0), and is capped at {@code 3} (level 4 is reserved for tenure).
307	     *
308	     * @return the owner's membership level
309	     */
310	    @Transient
311	    public Integer getMembershipLevel() {
312	        int level = 1;
313	        boolean hasEmail = this.email != null && !this.email.isBlank();
314	        if (hasEmail) {
315	            level++;
316	        }
317	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
318	        if (noNamesakes) {
319	            level++;
320	        }
321	        return Math.min(level, 3);
322	    }
323	
324	    /**
325	     * Returns this owner's membership number formatted as {@code '<customerCode>-M<YY>'}, where YY is
326	     * the last two digits of the registrationDate year, e.g. {@code 'NSW-A1B2C3D4-M26'}. Returns
327	     * {@code null} when the owner has no customer code or registration date.
328	     *
329	     * @return the owner's membership number, or {@code null} when it cannot be derived
330	     */
331	    @Transient
332	    public String getMembershipNumber() {
333	        if (this.customerCode == null || this.registrationDate == null) {
334	            return null;
335	        }
336	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
337	    }
338	
339	    /**
340	     * Returns this owner's check digit: a single Luhn check digit (0-9) over the digits contained in
341	     * the owner's customerCode. Returns {@code null} when the owner has no customer code.
342	     *
343	     * @return the owner's check digit, or {@code null} when it has no customer code
344	     */
345	    @Transient
346	    public Integer getCheckDigit() {
347	        if (this.customerCode == null) {
348	            return null;
349	        }
350	        String code = this.customerCode;
351	        int sum = 0;
352	        boolean dbl = true;
353	        for (int i = code.length() - 1; i >= 0; i--) {
354	            char c = code.charAt(i);
355	            if (c < '0' || c > '9') {
356	                continue;
357	            }
358	            int d = c - '0';
359	            if (dbl) {
360	                d *= 2;
361	                if (d > 9) {
362	                    d -= 9;
363	                }
364	            }
365	            sum += d;
366	            dbl = !dbl;
367	        }
368	        return (10 - (sum % 10)) % 10;
369	    }
370	
371	    /**
372	     * Returns this owner's age band, derived from {@code birthDate} computed against
373	     * {@code registrationDate}: the whole number of years between the two dates places the owner in
374	     * {@code 'MINOR'} (under 18), {@code 'ADULT'} (18 to 64 inclusive) or {@code 'SENIOR'} (65 or
375	     * older). Returns {@code null} when the owner has no birth date or no registration date, so the
376	     * band cannot be derived. This is the single definition of an owner's age band.
377	     *
378	     * @return the owner's age band, or {@code null} when it cannot be derived
379	     */
380	    @Transient
381	    public String getAgeBand() {
382	        if (this.birthDate == null || this.registrationDate == null) {
383	            return null;
384	        }
385	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
386	        if (age < 18) {
387	            return "MINOR";
388	        }
389	        if (age < 65) {
390	            return "ADULT";
391	        }
392	        return "SENIOR";
393	    }
394	
395	    protected Set<Pet> getPetsInternal() {
396	        if (this.pets == null) {
397	            this.pets = new HashSet<>();
398	        }
399	        return this.pets;
400	    }
401	
402	    protected void setPetsInternal(Set<Pet> pets) {
403	        this.pets = pets;
404	    }
405	
406	    public List<Pet> getPets() {
407	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
408	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
409	        return Collections.unmodifiableList(sortedPets);
410	    }
411	
412	    public void setPets(List<Pet> pets) {
413	        this.pets = new HashSet<>(pets);
414	    }
415	
416	    public void addPet(Pet pet) {
417	        getPetsInternal().add(pet);
418	        pet.setOwner(this);
419	    }
420	
421	    /**
422	     * Return the Pet with the given name, or null if none found for this Owner.
423	     *
424	     * @param name to test
425	     * @return true if pet name is already in use
426	     */
427	    public Pet getPet(String name) {
428	        return getPet(name, false);
429	    }
430	
431	    /**
432	     * Return the Pet with the given name, or null if none found for this Owner.
433	     *
434	     * @param name to test
435	     * @return true if pet name is already in use
436	     */
437	    public Pet getPet(String name, boolean ignoreNew) {
438	        name = name.toLowerCase();
439	        for (Pet pet : getPetsInternal()) {
440	            if (!ignoreNew || !pet.isNew()) {
441	                String compName = pet.getName();
442	                compName = compName.toLowerCase();
443	                if (compName.equals(name)) {
444	                    return pet;
445	                }
446	            }
447	        }
448	        return null;
449	    }
450	
451	    public Pet getPet(Integer petId) {
452	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
453	    }
454	
455	    @Override
456	    public String toString() {
457	        return new ToStringCreator(this)
458	
459	            .append("id", this.getId())
460	            .append("new", this.isNew())
461	            .append("lastName", this.getLastName())
462	            .append("firstName", this.getFirstName())
463	            .append("address", this.address)
464	            .append("city", this.city)
465	            .append("telephone", this.telephone)
466	            .append("email", this.email)
467	            .toString();
468	    }
469	}
