private void applyPossibleDuplicate(Owner owner) {
    owner.setPossibleDuplicate(false);
    owner.setPossibleDuplicateOf(null);
    findPossibleDuplicate(owner).ifPresent(existing -> {
        owner.setPossibleDuplicate(true);
